1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
10	 * an existing one — sharing the same last name and postcode but a different telephone (see
11	 * {@link PossibleDuplicate}). Such an owner is still created; the matching owner's id is
12	 * stored in {@code possibleDuplicateOf} so a later read can flag it.
13	 *
14	 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected household duplicates, so a
15	 * match reaching here can only be a declared household member ({@code sharesHousehold}). A
16	 * declared member is not a suspected duplicate, so it is never flagged; otherwise the
17	 * earliest-created (lowest id) matching owner is recorded, and no match leaves the field unset.
18	 */
19	public class FlagPossibleDuplicate {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            owner.setPossibleDuplicateOf(null); // a declared household member is not a suspected duplicate
24	            return;
25	        }
26	        Integer matchId = null;
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (PossibleDuplicate.matches(existing, owner)) {
29	                Integer id = existing.getId();
30	                if (id != null && (matchId == null || id < matchId)) {
31	                    matchId = id;
32	                }
33	            }
34	        }
35	        owner.setPossibleDuplicateOf(matchId);
36	    }
37	}
